from pathlib import Path
import base64,zlib
p=Path('index.html')
s=p.read_text(encoding='utf-8')
if 'data-build="ma-project-v80"' in s:
    raise SystemExit(0)
for a,b in [
('<title>ma.｜案件 v79</title>','<title>ma.｜案件 v80</title>'),
('version:79,','version:80,'),
('data-build="ma-project-v79"','data-build="ma-project-v80"'),
('const WORKSPACE_DOCK_KEY="maWorkspaceDockV79"','const WORKSPACE_DOCK_KEY="maWorkspaceDockV80"')]:
    if a not in s: raise SystemExit(f'missing marker: {a}')
    s=s.replace(a,b,1)
blob='' 
css=zlib.decompress(base64.b64decode(blob)).decode()
if 'Sketch Craft / full visual system' not in s:
    s=s.replace('</style>',css+'\n</style>',1)
p.write_text(s,encoding='utf-8')
print('patched to v80')
